SourceCode.Declaration:
/// <summary>
/// A warehouse worker's handheld login.
///
/// Deliberately separate from Entra ID. Warehouse workers routinely have no Microsoft account,
/// handhelds are shared across shifts, and a worker needs to sign in and out in seconds at a
/// receiving bay. This table is what makes a posting attributable to a person rather than to the
/// service principal the device authenticates with.
///
/// **This is a custom credential store, with everything that implies.** No MFA, no conditional
/// access, no central revocation through Entra, and no password policy unless one is enforced
/// here. It is appropriate for shop-floor identity layered on top of a service-principal
/// transport; it is not a replacement for Entra ID for anyone who has one.
///
/// The password itself is never stored, and never reaches this table. Only a PBKDF2 hash and the
/// salt it was derived with - see HSMobileOpsPassword.
/// </summary>
public class HSMobileOpsUser extends common
{
}

Method.Source:
/// <summary>
/// Finds a user by name, case-insensitively.
///
/// Case folding matters: an operator typing their own name at a bay will not reliably match
/// the case it was created with, and "wrong password" for a case mismatch is the kind of
/// failure that has people convinced the app is broken.
/// </summary>
public static HSMobileOpsUser find(HSMobileOpsUserName _userName, boolean _forUpdate = false)
{
    HSMobileOpsUser user;

    if (!_userName)
    {
        return user;
    }

    user.selectForUpdate(_forUpdate);

    select firstOnly user
        where user.UserName == _userName;

    return user;
}

/// <summary>
/// Whether failed attempts have locked this account for now.
///
/// A time-boxed lockout rather than a permanent one. A permanent lock needs an administrator
/// to clear it, and on a night shift with nobody to call that means the work stops - so the
/// common case of a mistyped password costs a wait, not an escalation.
/// </summary>
public boolean isLockedOut()
{
    return this.LockedUntilUtc
        && DateTimeUtil::utcNow() < this.LockedUntilUtc;
}
